// Everything `kohaku init --mcp` adds on top of the REST-only project: the MCP front-door file templates, the
// package.json dependencies and scripts, the README sections, the .gitignore extra, the Claude Desktop config
// and the report hint. `render.ts`, `index.ts` and `report.ts` call these at the same positions where the
// `--mcp` branches used to be inline, so the generated bytes are unchanged (pinned by
// test/init/render-golden.test.ts).
import { join } from "node:path";
import { CLI_VERSION } from "../version.js";
import type { ProjectFile } from "./render.js";
import { SHUTDOWN_GRACE_SNIPPET } from "./templates.js";
import { EXTERNAL_VERSIONS } from "./versions.js";

/** The `package.json` dependencies the MCP front door adds (merged into the sorted dependency list by the caller). */
export function mcpDependencies(): Record<string, string> {
  return {
    "@kohaku-ui/host-mcp-apps": `^${CLI_VERSION}`,
    "@kohaku-ui/mcp-renderer": `^${CLI_VERSION}`,
    "@modelcontextprotocol/server": EXTERNAL_VERSIONS["@modelcontextprotocol/server"],
    "@modelcontextprotocol/node": EXTERNAL_VERSIONS["@modelcontextprotocol/node"],
  };
}

/** The `package.json` scripts the MCP front door adds, in the order they are emitted after the base scripts. */
export const MCP_SCRIPTS = {
  mcp: "tsx server/mcp.ts",
  "mcp:http": "tsx server/mcp-http.ts",
  "mcp:claude-desktop": "node scripts/claude-desktop.mjs",
} as const;

/** The MCP front door's project files, in the order `renderProjectFiles` emits them (between server/app.ts and server/main.ts). */
export function mcpProjectFiles(name: string): ProjectFile[] {
  const nameReplaced = (template: string): string => template.replaceAll("__NAME__", name);
  return [
    { path: "server/mcp-server.ts", content: MCP_SERVER_TEMPLATE },
    { path: "server/mcp.ts", content: nameReplaced(MCP_STDIO_TEMPLATE) },
    { path: "server/mcp-http.ts", content: nameReplaced(MCP_HTTP_TEMPLATE) },
    { path: "scripts/claude-desktop.mjs", content: CLAUDE_DESKTOP_SCRIPT_TEMPLATE },
  ];
}

